import{z as s,x as i,o as l,c as C,q as t,j as r,D as B,d as A,s as o,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"MLC 走读","description":"","frontmatter":{"title":"MLC 走读","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fw-mlc-walkthrough.md","filePath":"llm/fw-mlc-walkthrough.md","lastUpdated":1791063341000}'),d={name:"llm/fw-mlc-walkthrough.md"};function h(m,E,p,F,D,f){const e=i("Mermaid");return l(),C("div",null,[E[2]||(E[2]=t('<h1 id="mlc-走读" tabindex="-1">MLC 走读 <a class="header-anchor" href="#mlc-走读" aria-label="Permalink to &quot;MLC 走读&quot;">​</a></h1><div class="epigraph"><p>编译框架的接口长相反常：运行时最厚的文件不在算计算，而在按名字调用编译产物里那张函数表。</p><footer>—— 据 Chen 等，TVM，OSDI 2018 与 MLC-LLM 仓库文档整理</footer></div><p><a href="/llm/fw-llamacpp-walkthrough">上一课</a>的手写多后端靠人力覆盖设备，MLC 把这件事交给编译器：同一前端、多份代码生成，概念面已写过——一前端多 codegen、动态序列是 LLM 多出来的编译难题，见 <a href="/llm/mlc-tvm">MLC / TVM 编译</a>。本课进仓库讲编译管线与运行时的分层，以及编译框架特有的数据结构，以仓库当时状态为准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>拿解释器式运行时的读法进来，会发现自己读的文件都在「不干活」：Python 层的引擎类里没有矩阵乘法，只有请求状态机和对编译产物的调用。MLC 的执行体是<strong>编译出来的库</strong>：模型被降成虚拟机字节码加设备代码，调度原语在构建期搜索选定。于是走读的问题与 TensorRT-LLM 课同型——构建期浇死了什么——但多出一问：分页 KV 这种带策略的状态，住进编译产物还是留在宿主语言里。</p><p><span class="marginnote">常见误区：以为「读 MLC 源码就是读它怎么算矩阵乘」。实际上那些计算代码是编译器生成的、仓库里根本没有——源码里能读的是「生成计算的程序」和「调用计算结果的程序」。类比：你读不到菜谱本身（编译期才产出），能读到的是写菜谱的厨师手册和服务员的上菜流程。</span></p><h3 id="三段管线" tabindex="-1">三段管线 <a class="header-anchor" href="#三段管线" aria-label="Permalink to &quot;三段管线&quot;">​</a></h3><p>第一段编译：从开源权重导入计算图，降到中间表示，做融合与布局改写，对注意力与矩阵乘的调度空间做自动调优，产出共享库与一份元数据描述——显存预算、缓存规模、暴露的函数名都在这份元数据里。第二段打包：模型库、量化后的权重目录与配置放在一起，成为可分发的部署物。第三段运行：宿主侧引擎持有编译产物，把请求翻译成对具名函数的调用。浏览器与移动端走同一套产物，只是宿主换成 WebGPU 或原生运行时，见端侧路径的 <a href="/llm/npu-friendly-ops">NPU 友好算子</a>。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>沿一步解码走，锚点是那张<strong>函数表</strong>。编译产物按名字暴露入口：预填充、解码、嵌入、以及缓存管理操作。宿主引擎每步做的事是：把本批的 token、位置与页表装进参数，按名字调用入口，收回 logits。分页 KV 缓存是运行时的关键数据结构，它不是宿主语言的对象，而是编译产物侧的<strong>不透明对象</strong>：分配、淘汰、按页读写都由编译期内实现，宿主只持句柄——策略被写进编译产物，这正是与手写运行时最大的结构差异。请求状态机、流式回调、OpenAI 兼容协议则全在宿主 Python 层，接口形态与 <a href="/llm/vllm-architecture">vLLM</a> 的异步引擎几乎同构。</p><p><span class="marginnote">术语翻译：「不透明对象」就是宿主只拿到一张取货凭证（句柄），看不见里面的字段和布局，所有操作都要通过编译产物提供的函数来办。像把贵重物品存进银行保险柜：你拿着钥匙编号，但柜子内部结构、谁在什么时候动过，全由银行（编译产物内部代码）管理。</span></p>',11)),(l(),r(n,null,{default:B(()=>[o(e,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20HF%5B%22%E5%BC%80%E6%BA%90%E6%9D%83%E9%87%8D%22%5D%20--%3E%20IR%5B%22%E4%B8%AD%E9%97%B4%E8%A1%A8%E7%A4%BA%EF%BC%9A%E8%9E%8D%E5%90%88%E4%B8%8E%E5%B8%83%E5%B1%80%22%5D%0A%20%20IR%20--%3E%20TUNE%5B%22%E8%B0%83%E5%BA%A6%E7%A9%BA%E9%97%B4%E8%87%AA%E5%8A%A8%E8%B0%83%E4%BC%98%22%5D%0A%20%20TUNE%20--%3E%20LIB%5B%22%E7%BC%96%E8%AF%91%E4%BA%A7%E7%89%A9%EF%BC%9A%E5%BA%93%20%2B%20%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20LIB%20--%3E%20ENG%5B%22%E5%AE%BF%E4%B8%BB%E5%BC%95%E6%93%8E%EF%BC%88Python%EF%BC%89%22%5D%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E4%B8%8E%E6%B5%81%E5%BC%8F%E5%8D%8F%E8%AE%AE%22%5D%20--%3E%20ENG%0A%20%20ENG%20--%3E%7C%E6%8C%89%E5%90%8D%E5%AD%97%E8%B0%83%E7%94%A8%E5%85%A5%E5%8F%A3%7C%20FT%5B%22%E5%87%BD%E6%95%B0%E8%A1%A8%EF%BC%9A%E9%A2%84%E5%A1%AB%E5%85%85%20%2F%20%E8%A7%A3%E7%A0%81%20%2F%20%E5%B5%8C%E5%85%A5%22%5D%0A%20%20FT%20--%3E%20KVO%5B%22%E5%88%86%E9%A1%B5%20KV%20%E7%BC%93%E5%AD%98%EF%BC%9A%E7%BC%96%E8%AF%91%E4%BA%A7%E7%89%A9%E4%BE%A7%E4%B8%8D%E9%80%8F%E6%98%8E%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20FT%20--%3E%7Clogits%7C%20ENG%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"元数据文件在打包时就给出显存核算：缓存页数、权重占用、运行时余量一目了然。这把「这个模型在这块卡上放不放得下」从运行期报错提前到部署期检查，是编译路线容易被忽略的工程红利。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[A("策略下沉与协议留宿主的分工，来自编译边界的天然切分：张量程序必须静态可生成，所以缓存布局与读写原语被写成编译期代码；请求生命周期要接生态，所以协议、分词、流式留在宿主语言。换硬件时，宿主引擎一行不改，换的是编译目标与产物——这是「可移植」在源码层的精确含义：不是一份二进制跑遍天下，而是一份宿主代码配多份产物。代价同样在结构上可见：优化上限被调度模板与代码生成质量封顶，CUDA 上常借 "),a("a",{href:"/llm/flashinfer"},"FlashInfer"),A(" 这类现成核补足注意力，产物里就会同时存在编译核与库核两条路径。")],-1)),(l(),r(n,null,{default:B(()=>[o(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20HOST%5B%22%E5%AE%BF%E4%B8%BB%E8%AF%AD%E8%A8%80%EF%BC%88Python%20%2F%20JS%EF%BC%89%EF%BC%9A%E9%9A%8F%E7%94%9F%E6%80%81%E8%B5%B0%22%5D%0A%20%20%20%20H1%5B%22%E8%AF%B7%E6%B1%82%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20%20%20H2%5B%22OpenAI%20%E5%85%BC%E5%AE%B9%E5%8D%8F%E8%AE%AE%E4%B8%8E%E6%B5%81%E5%BC%8F%22%5D%0A%20%20%20%20H3%5B%22%E5%88%86%E8%AF%8D%20%2F%20%E5%8F%8D%E5%88%86%E8%AF%8D%22%5D%0A%20%20end%0A%20%20subgraph%20LIB%5B%22%E7%BC%96%E8%AF%91%E4%BA%A7%E7%89%A9%EF%BC%88%E5%BA%93%20%2B%20%E5%AD%97%E8%8A%82%E7%A0%81%20%2B%20%E8%AE%BE%E5%A4%87%E4%BB%A3%E7%A0%81%EF%BC%89%EF%BC%9A%E9%9A%8F%E7%9B%AE%E6%A0%87%E9%87%8D%E7%BC%96%22%5D%0A%20%20%20%20L1%5B%22%E7%9F%A9%E9%98%B5%E4%B9%98%20%2F%20%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%A0%B8%22%5D%0A%20%20%20%20L2%5B%22%E5%88%86%E9%A1%B5%20KV%20%E7%9A%84%E5%88%86%E9%85%8D%E4%B8%8E%E6%B7%98%E6%B1%B0%E7%AD%96%E7%95%A5%22%5D%0A%20%20%20%20L3%5B%22%E5%87%BD%E6%95%B0%E8%A1%A8%E5%85%A5%E5%8F%A3%22%5D%0A%20%20end%0A%20%20H1%20--%3E%7C%22%E5%85%B7%E5%90%8D%E8%B0%83%E7%94%A8%22%7C%20L3%0A%20%20L3%20--%3E%20L1%0A%20%20L3%20--%3E%20L2%0A%20%20L1%20--%3E%7C%22logits%20%2F%20token%22%7C%20H3%0A%20%20SW%5B%22%E6%8D%A2%20GPU%20%2F%20%E6%B5%8F%E8%A7%88%E5%99%A8%20%2F%20%E6%89%8B%E6%9C%BA%22%5D%20-.%20%22%E5%8F%AA%E9%87%8D%E7%BC%96%E8%BF%99%E4%B8%80%E4%BE%A7%EF%BC%8C%E5%AE%BF%E4%B8%BB%E4%B8%8D%E5%8A%A8%22%20.-%3E%20LIB%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>版本敏感处照例注明：中间表示与打包格式随编译器主线演进，函数表入口名以仓库当时状态为准。自动调优的搜索成本落在部署侧，产物的性能方差比手写运行时大；浏览器路径无多租户语义，与服务器引擎不可同表而论。本课不重讲调度原语与张量化，那在 <a href="/llm/mlc-tvm">MLC / TVM 编译</a>已完成；PD 分离与跨实例迁移这类系统特性不在它的主场。</p><p><span class="marginnote">为什么「显存核算前置」重要：手写运行时里，缓存开多大常常是运行期动态决定，放不下就 OOM 报错；编译路线把页数在部署期算死，部署前就知道这块卡放不放得下。类比：一个是装修完才发现沙发进不了门，一个是下单前先量门框。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MLC 是三段管线：编译成库与元数据、打包部署物、宿主引擎按函数表调用。</li><li>走读锚点是具名函数表与编译产物侧的分页 KV 不透明对象：策略下沉进产物，协议留在宿主。</li><li>元数据在部署期给足显存核算，容量问题前置，不再靠运行期撞墙。</li><li>可移植的精确含义是宿主不变、产物随目标重编，而不是一份二进制通吃。</li><li>优化上限由调度模板与代码生成决定，CUDA 上常以现成注意力库补强；入口名以仓库当时状态为准。</li><li>出处：Chen et al., <em>TVM</em>, OSDI 2018 与 MLC-LLM 仓库文档，按源码结构整理。</li></ul>',5))])}const c=s(d,[["render",h]]);export{u as __pageData,c as default};
